CREATE SCHEMA shop;
CREATE SCHEMA audit;
CREATE TABLE shop.widget (id BIGINT PRIMARY KEY, label VARCHAR(100), colour VARCHAR(20), weight INTEGER);
CREATE TABLE shop.orders (id BIGINT PRIMARY KEY, widget_id BIGINT REFERENCES shop.widget(id), total NUMERIC(10,2));
CREATE TABLE shop.shipments (id BIGINT PRIMARY KEY, sent DATE);
CREATE VIEW shop.order_totals AS SELECT id, total FROM shop.orders;
CREATE TABLE audit.log (id BIGINT PRIMARY KEY, message TEXT);

package com.example.shop.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "widget")
public class Widget {

    @Id
    private Long id;

    @Column(name = "label")
    private String label;
}
